```ts
// Cancel a task
const downloadTask = downloadData({ path });
//...
downloadTask.cancel();
try {
	await downloadTask.result;
} catch (error) {
	if(isCancelError(error)) {
   // Handle error thrown by task cancelation.
	}
}
